UPDATE pull_task_pull_call
SET call_status = #{targetStatus},
    command_id = #{commandId},
    submitted_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND call_status = #{expectedStatus}

UPDATE pull_task_pull_call
SET puller_group_account_id = #{reassignment.target.groupAccountId},
    puller_account_id = #{reassignment.target.accountId},
    updated_at = #{reassignment.now}
WHERE id = #{reassignment.id}
  AND puller_group_account_id = #{reassignment.expectedPullerGroupAccountId}
  AND call_status = #{reassignment.expectedStatus}

UPDATE pull_task_pull_call
SET puller_group_account_id = #{binding.target.pullerGroupAccountId},
    puller_account_id = #{binding.target.pullerAccountId},
    puller_assignment_seq = #{binding.target.assignmentSeq},
    updated_at = #{binding.now}
WHERE id = #{binding.scope.pullCallId}
  AND ((#{binding.scope.expectedPullerGroupAccountId} IS NULL
        AND puller_group_account_id IS NULL)
    OR puller_group_account_id = #{binding.scope.expectedPullerGroupAccountId})
  AND call_status = #{binding.scope.expectedCallStatus}

UPDATE pull_task_pull_call
SET planned_material_count = planned_material_count
      - CASE WHEN #{prune.participantType} = #{prune.target.materialParticipantType}
        THEN 1 ELSE 0 END,
    planned_station_count = planned_station_count
      - CASE WHEN #{prune.participantType} = #{prune.target.stationParticipantType}
        THEN 1 ELSE 0 END,
    call_status = CASE
      WHEN planned_material_count + planned_station_count = 1
        THEN #{prune.target.canceledCallStatus}
      ELSE call_status
    END,
    reason_code = CASE
      WHEN planned_material_count + planned_station_count = 1
        THEN #{prune.target.emptyCallReasonCode}
      ELSE reason_code
    END,
    reason_message = CASE
      WHEN planned_material_count + planned_station_count = 1
        THEN #{prune.target.emptyCallReasonMessage}
      ELSE reason_message
    END,
    result_at = CASE
      WHEN planned_material_count + planned_station_count = 1 THEN #{prune.now}
      ELSE result_at
    END,
    updated_at = #{prune.now}
WHERE id = #{prune.pullCallId}
  AND call_status = #{prune.expectedCallStatus}
  AND ((#{prune.participantType} = #{prune.target.materialParticipantType}
        AND planned_material_count > 0)
    OR (#{prune.participantType} = #{prune.target.stationParticipantType}
        AND planned_station_count > 0))

UPDATE pull_task_pull_call
SET pull_wave_id = #{binding.target.pullWaveId},
    wave_call_seq = #{binding.target.waveCallSeq},
    updated_at = #{binding.now}
WHERE id = #{binding.scope.callId}
  AND group_execution_id = #{binding.scope.groupExecutionId}
  AND pull_wave_id IS NULL
  AND call_status IN
  #{status}

UPDATE pull_task_pull_call
SET puller_assignment_seq = #{binding.assignmentSeq},
    updated_at = #{binding.now}
WHERE id = #{binding.pullCallId}
  AND puller_group_account_id = #{binding.pullerGroupAccountId}
  AND puller_assignment_seq IS NULL

UPDATE pull_task_pull_call
SET call_status = #{transition.targetStatus},
    reason_code = #{transition.result.reasonCode},
    reason_message = #{transition.result.reasonMessage},
    result_at = #{transition.now},
    updated_at = #{transition.now}
WHERE id = #{transition.id}
  AND call_status IN
  #{status}

