SET roster_check_status = #{targetStatus},
    roster_check_started_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND roster_check_status = #{expectedStatus}

UPDATE pull_task_pull_call
SET roster_check_status = #{targetStatus},
    roster_check_finished_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND roster_check_status = #{expectedStatus}

UPDATE pull_task_pull_call
SET call_status = #{targetStatus},
    result_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND call_status = #{expectedStatus}

UPDATE pull_task_pull_call
SET call_status = #{targetStatus},
    result_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND call_status = #{expectedStatus}

UPDATE pull_task_pull_call
SET call_status = #{targetStatus},
    result_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}

    AND group_execution_id = #{groupExecutionId}

  AND call_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM protocol_command_outbox outbox_row
    WHERE outbox_row.command_id = pull_task_pull_call.command_id
      AND outbox_row.status = #{canceledOutboxStatus}
      AND outbox_row.deleted_at IS NULL
  )
